  // --- Additional known-safe API return branding ---
  interface Dimension {
    getTopmostBlock(
      locationXZ: Minecraft.VectorXZ,
      minHeight?: number
    ): ValidBlock | undefined;
    getBlockAbove(
      location: Minecraft.Vector3,
      options?: Minecraft.BlockRaycastOptions
    ): ValidBlock | undefined;
    getBlockBelow(
      location: Minecraft.Vector3,
      options?: Minecraft.BlockRaycastOptions
    ): ValidBlock | undefined;
    getBlockFromRay(
      location: Minecraft.Vector3,
      direction: Minecraft.Vector3,
      options?: Minecraft.BlockRaycastOptions
    ):
      | {
          block: ValidBlock;
          face: Minecraft.Direction;
          faceLocation: Minecraft.Vector3;
        }
      | undefined;
    getEntitiesFromRay(
      location: Minecraft.Vector3,
      direction: Minecraft.Vector3,
      options?: Minecraft.EntityRaycastOptions
    ): { distance: number; entity: ValidEntity }[];
    spawnEntity<T = never>(
      identifier: Minecraft.EntityIdentifierType<NoInfer<T>>,
      location: Minecraft.Vector3,
      options?: Minecraft.SpawnEntityOptions
    ): ValidEntity;
    spawnItem(
      itemStack: Minecraft.ItemStack,
      location: Minecraft.Vector3
    ): ValidEntity;
  }

  // Event methods are functions, so ValidCallbackValue leaves them unbranded —
  // overload return types for getters that expose live handles.
  interface ProjectileHitBlockAfterEvent {
    getBlockHit(): {
      block: ValidBlock;
      face: Minecraft.Direction;
      faceLocation: Minecraft.Vector3;
    };
  }
  // ProjectileHitEntityAfterEvent.getEntityHit() is intentionally NOT branded:
  // by after-event dispatch the hit entity may already have died and despawned.
  interface ExplosionAfterEvent {
    getImpactedBlocks(): ValidBlock[];
  }

  // --- Custom component registry overloads ---
  interface BlockComponentRegistry {
    registerCustomComponent(
      name: string,
      customComponent: ValidBlockCustomComponent
    ): void;
  }
  interface ItemComponentRegistry {
    registerCustomComponent(
      name: string,
      itemCustomComponent: ValidItemCustomComponent
    ): void;
  }

